        }

        // Check if sequence alternates properly for Gray code property
        // For a valid closed curve, adjacent elements in the sequence 
        // must differ by exactly one bit when interpreted as subset masks.

        // First convert to bit counts
        int[] counts = new int[len];
        for (int i = 0; i < len; i++) {
            counts[i] = Integer.bitCount(i);
        }

        // Check if the sequence visits each subset exactly once
        boolean[] seen = new boolean[len];
        for (int i = 0; i < len; i++) {
            if (seen[seq[i]]) {
                System.out.println("impossible");
                return;
            }
            seen[seq[i]] = true;
        }

        // Check adjacency: adjacent in sequence must differ by exactly 1 bit
        for (int i = 0; i < len; i++) {
            int a = seq[i];
            int b = seq[(i + 1) % len];
            int diff = a ^ b;
            if (Integer.bitCount(diff) != 1) {
                System.out.println("impossible");
                return;
            }
        }

        // Construct curve: use y = index of the first differing bit / (N+1)
        // and x = position in sequence scaled to [0,1].
        System.out.println("possible");
        for (int i = 0; i < len; i++) {
            int cur = seq[i];
            int next = seq[(i + 1) % len];
            int diffBit = 0;
            int xor = cur ^ next;
            while ((xor & 1) == 0) {
                xor >>= 1;
                diffBit++;
            }
            double x1 = (double) i / len;
            double x2 = (double) (i + 1) / len;
            double y = (double) (diffBit + 1) / (N + 1);
