public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int m = 1 << N;
        int[] a = new int[m];
        for (int i = 0; i < m; i++) a[i] = fs.nextInt();

        for (int mask = 0; mask < m; mask++) {
            if (a[mask] == 1) continue;
            for (int b = 0; b < N; b++) {
                if ((mask & (1 << b)) == 0) {
                    int sup = mask | (1 << b);
                    if (a[sup] < a[mask]) {
                        // impossible only if 1 -> 0; this branch never triggers for a[mask]==0
                    }
                }
            }
        }

        boolean ok = true;
        for (int mask = 0; mask < m && ok; mask++) {
            for (int b = 0; b < N; b++) {
                if ((mask & (1 << b)) == 0) {
                    int sup = mask | (1 << b);
                    if (a[mask] > a[sup]) {
                        ok = false;
                        break;
                    }
                }
            }
        }

        System.out.println(ok ? "YES" : "NO");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
